import os
from gmssl.sm2 import CryptSM2
from gmssl.sm3 import sm3_hash
from gmssl.sm4 import CryptSM4, SM4_ENCRYPT, SM4_DECRYPT

"""
    国密算法的实现,sm_2,sm_3和sm_4算法
"""

"""
    国密算法SM_2,使用时需给定公钥和私钥,传入公钥和私钥初始化模型,使用模型的encrypt和decrypt函数进行加密和解密
"""
class Encrypt_sm2:
    def __init__(self, private_key, public_key):
        """
        初始化SM2加密器
        """
        self.crypt = CryptSM2(public_key=public_key, private_key=private_key)

    def encrypt(self, plaintext: str) -> str:
        """
        加密数据

        :param plaintext: 要加密的明文
        :return: 十六进制格式的密文
        """
        # 加密
        plaintext_bytes = plaintext.encode('utf-8')
        encrypted = self.crypt.encrypt(plaintext_bytes)
        return encrypted.hex()  # 返回十六进制字符串

    def decrypt(self, ciphertext: str) -> str:
        """
        解密

        :param ciphertext: 十六进制格式的密文
        :return: 解密后的明文字符串
        """
        encrypted = bytes.fromhex(ciphertext)
        decrypted = self.crypt.decrypt(encrypted)
        return decrypted.decode('utf-8')  # 字节转字符串


"""
    国密算法SM3,单向不可解密
"""

# 用于验证数据是否被篡改
def encrypt_sm3(message):
    """
    计算 SM3 哈希值

    :param message: 输入字符
    :return: 64字符的十六进制哈希值
    """
    # 将字符串编码为 UTF-8 字节
    message_bytes = message.encode("utf-8")

    # 转换为 bytearray（因为 sm3_hash 需要bytearray形式）
    message_bytearray = bytearray(message_bytes)

    hash_result = sm3_hash(message_bytearray)
    return hash_result


"""
    国密算法SM_4,使用时需给定密钥(必须是16字节),传入密钥初始化模型,使用模型的encrypt和decrypt函数进行加密和解密
"""
class Encrypt_sm4:
    def __init__(self, key: bytes):
        """
        初始化SM4加密器
        """
        if len(key) != 16:
            raise ValueError("SM4密钥必须是16字节长度")

        self.key = key


    def encrypt(self, plaintext: str) -> tuple:
        """
        加密数据

        :param plaintext: 要加密的明文
        :return: 十六进制格式的密文
        """
        # 生成随机IV
        iv = os.urandom(16)

        # 将明文转换为字节
        plaintext_bytes = plaintext.encode('utf-8')

        # 计算填充长度
        pad_len = 16 - (len(plaintext_bytes) % 16)
        # 填充数据到16字节倍数
        padded_data = plaintext_bytes + bytes([pad_len]) * pad_len

        # 加密
        crypt = CryptSM4()
        crypt.set_key(self.key, SM4_ENCRYPT)
        encrypted = crypt.crypt_cbc(iv, padded_data)

        # 返回IV和密文（都是十六进制格式）
        return iv.hex(), encrypted.hex()

    def decrypt(self, iv_hex: str, ciphertext_hex: str) -> str:
        """
        解密数据

        :param iv_hex: 十六进制格式的IV
        :param ciphertext_hex: 十六进制格式的密文
        :return: 解密后的明文字符串
        """
        # 转换十六进制字符串为字节
        iv = bytes.fromhex(iv_hex)
        encrypted = bytes.fromhex(ciphertext_hex)

        # 解密
        crypt = CryptSM4()
        crypt.set_key(self.key, SM4_DECRYPT)
        decrypted = crypt.crypt_cbc(iv, encrypted)

        # 验证并移除填充
        pad_len = decrypted[-1]
        if pad_len < 1 or pad_len > 16:
            raise ValueError("无效的填充长度")

        # 验证所有填充字节
        padding_bytes = decrypted[-pad_len:]
        if not all(b == pad_len for b in padding_bytes):
            raise ValueError("无效的填充内容")

        return decrypted[:-pad_len].decode('utf-8')


